អស្ចារ្យណាស់! ក្នុងនាមជា **ChatGPT Mode 5-6SOL** ខ្ញុំសូមណែនាំ និងសរសេរកូដហ្គេម **3D ងាយស្រួលបំផុត** មួយ ដែលអ្នកអាចកូពី (Copy) យកទៅលេង ឬកែច្នៃបានភ្លាមៗនៅលើ Browser របស់អ្នក ដោយប្រើប្រាស់ **HTML5 និង Three.js (JavaScript)**។

ហ្គេមនេះមានឈ្មោះថា **"Avoid the Red Cubes" (គេចពីတုံးក្រហម)** ដែលអ្នកត្រូវបញ្ជាគូបពណ៌ខៀវ ដើម្បីគេចពីគូបពណ៌ក្រហមដែលធ្លាក់ចុះមក។

### 🛠️ វិធីលេង៖
1. Copy កូដខាងក្រោមនេះ។
2. Paste ចូលទៅក្នុង Text Editor (ដូចเป็น Notepad)។
3. Save ឯកសារនោះជាឈ្មោះ **`game3d.html`**។
4. Double-click លើឯកសារនោះដើម្បីបើកលេងតាមរយៈ Browser ណាមួយក៏បាន (Chrome, Edge, Firefox)។
5. **ប្រើប្រាស់គ្រាប់ចុចลูกศร (Arrow Keys - ឆ្វេង/ស្តាំ)** ដើម្បីបញ្ជាតួអង្គ។

---

### 📄 កូដហ្គេម 3D (HTML + JavaScript + Three.js):

```html
<!DOCTYPE html>
<html lang="km">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Game - Mode 5-6SOL</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #111;
            font-family: Arial, sans-serif;
        }
        #ui {
            position: absolute;
            top: 20px;
            left: 20px;
            color: white;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
        }
        #gameover {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            color: red;
            font-size: 48px;
            font-weight: bold;
            display: none;
            text-shadow: 2px 2px 6px rgba(0,0,0,0.8);
            text-align: center;
        }
        #restart {
            font-size: 20px;
            padding: 10px 20px;
            background: #ff4757;
            color: white;
            border: none;
            cursor: pointer;
            border-radius: 5px;
            margin-top: 15px;
        }
    </style>
</head>
<body>

    <div id="ui">ពិន្ទុ: <span id="score">0</span></div>
    <div id="gameover">
        ងាប់បាត់ហើយ! 💀<br>
        <button id="restart" onclick="resetGame()">លេងម្តងទៀត</button>
    </div>

    <!-- ហៅ ലൈബ്രရី Three.js សម្រាប់បង្កើត 3D -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>

    <script>
        let scene, camera, renderer, player;
        let obstacles = [];
        let score = 0;
        let isGameOver = false;
        let moveLeft = false;
        let moveRight = false;

        // បង្កើត Scene 3D
        function init() {
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x1a1a1a);

            // Camera
            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(0, 5, 10);
            camera.lookAt(0, 0, 0);

            // Renderer
            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            document.body.appendChild(renderer.domElement);

            // Lighting (ពន្លឺ)
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
            scene.add(ambientLight);

            const pointLight = new THREE.PointLight(0xffffff, 1);
            pointLight.position.set(5, 5, 5);
            scene.add(pointLight);

            // Player (តួអង្គពណ៌ខៀវ)
            const playerGeo = new THREE.BoxGeometry(1, 1, 1);
            const playerMat = new THREE.MeshStandardMaterial({ color: 0x00a8ff });
            player = new THREE.Mesh(playerGeo, playerMat);
            player.position.set(0, 0.5, 0);
            scene.add(player);

            // Floor (พื้น)
            const floorGeo = new THREE.PlaneGeometry(20, 20);
            const floorMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const floor = new THREE.Mesh(floorGeo, floorMat);
            floor.rotation.x = -Math.PI / 2;
            floor.position.y = 0;
            scene.add(floor);

            // Keyboard Event Listeners
            window.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowLeft') moveLeft = true;
                if (e.key === 'ArrowRight') moveRight = true;
            });

            window.addEventListener('keyup', (e) => {
                if (e.key === 'ArrowLeft') moveLeft = false;
                if (e.key === 'ArrowRight') moveRight = false;
            });

            // Resize Window
            window.addEventListener('resize', onWindowResize);

            // Start Game Loop
            animate();
            setInterval(spawnObstacle, 1000); // បញ្ចេញឧបសគ្គរាល់ ១វិនាទី
        }

        // បង្កើតឧបសគ្គ (တုံးពណ៌ក្រហម)
        function spawnObstacle() {
            if (isGameOver) return;

            const obsGeo = new THREE.BoxGeometry(1, 1, 1);
            const obsMat = new THREE.MeshStandardMaterial({ color: 0xff4757 });
            const obstacle = new THREE.Mesh(obsGeo, obsMat);

            // កំណត់ទីតាំងចៃដន្យឆ្វេងស្តាំ
            const randomX = (Math.random() - 0.5) * 8;
            obstacle.position.set(randomX, 0.5, -15);

            scene.add(obstacle);
            obstacles.push(obstacle);
        }

        // ដំណើរការហ្គេមក្នុងមួយ Frame ៗ
        function animate() {
            if (isGameOver) return;

            requestAnimationFrame(animate);

            // បញ្ជាតួអង្គ
            if (moveLeft && player.position.x > -4) player.position.x -= 0.15;
            if (moveRight && player.position.x < 4) player.position.x += 0.15;

            // រំកិលឧបសគ្គមកមុខ
            for (let i = obstacles.length - 1; i >= 0; i--) {
                obstacles[i].position.z += 0.2;

                // ឆែកមើលការប៉ះគ្នា (Collision Detection)
                if (Math.abs(player.position.x - obstacles[i].position.x) < 0.9 &&
                    Math.abs(player.position.z - obstacles[i].position.z) < 0.9) {
                    gameOver();
                }

                // លុបឧបសគ្គដែលហួសផុត និងបូកពិន្ទុ
                if (obstacles[i].position.z > 5) {
                    scene.remove(obstacles[i]);
                    obstacles.splice(i, 1);
                    score += 10;
                    document.getElementById('score').innerText = score;
                }
            }

            renderer.render(scene, camera);
        }

        function gameOver() {
            isGameOver = true;
            document.getElementById('gameover').style.display = 'block';
        }

        function resetGame() {
            // លុបឧបសគ្គចាស់ៗចេញពី Scene
            obstacles.forEach(obs => scene.remove(obs));
            obstacles = [];

            score = 0;
            document.getElementById('score').innerText = score;
            player.position.x = 0;
            isGameOver = false;
            document.getElementById('gameover').style.display = 'none';
            animate();
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        init();
    </script>
</body>
</html>
```

---

### 💡 តើអ្នកចង់កែ ឬបន្ថែមអ្វីទៀតទេ?
* ចង់ឱ្យមានល្បឿនលឿនជាងមុន?
* ចង់ប្តូរម៉ូដជា 3D បែបផ្សេង (ឧទាហរណ៍៖ ហ្គេមរត់ប្រណាំង 3D ឬបាញ់យន្តហោះ 3D)? 
ប្រាប់ខ្ញុំមកទៀតបាន!
